package com.zhibrary.admin;
import com.zhibrary.book.*; import com.zhibrary.borrow.*; import com.zhibrary.user.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @CrossOrigin(origins="http://localhost:5173") public class AdminController { private final BookRepository books;private final UserRepository users;private final BorrowRepository records; public AdminController(BookRepository b,UserRepository u,BorrowRepository r){books=b;users=u;records=r;} @GetMapping("/summary") public Map<String,Object> summary(){return Map.of("totalBooks",books.count(),"available",books.countByStatus(BookStatus.AVAILABLE),"borrowed",books.countByStatus(BookStatus.BORROWED),"lost",books.countByStatus(BookStatus.LOST),"maintenance",books.countByStatus(BookStatus.UNDER_MAINTENANCE),"users",users.countByRole(UserRole.USER),"overdue",records.findByStatus(BorrowStatus.ACTIVE).stream().filter(r->r.getDueDate().isBefore(java.time.LocalDate.now())).count());} @GetMapping("/overdue") public List<BorrowRecord> overdue(){return records.findByStatus(BorrowStatus.ACTIVE).stream().filter(r->r.getDueDate().isBefore(java.time.LocalDate.now())).toList();} @GetMapping("/members") public List<User> members(){return users.findAll();} }
